  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TYMO Partner Program (tiered affiliate program, no earning cap)', 'https://tymobeauty.com/pages/tymo-partner', 'https://tymobeauty.com/pages/tymo-partner', 'unverified', 'ugc');
