  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tymobeauty.com/en-de/pages/affiliate-policy', 'official_site', 'affiliate', 'TYMO''s published Affiliate Program Terms & Conditions state payouts run on a 30-day cycle through the Social Snowball platform (the terms also list ShareASale, PartnerBoost, GoAffPro, Awin and Impact as cooperating platforms) and publish the affiliate support email affiliate@tymo-tech.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tymobeauty.com/pages/tymo-partner', 'official_site', 'ugc_collab', 'The partner page is built around creator content: it instructs partners to post reviews and demos, publishes top-affiliate earnings testimonials (one affiliate shown with $12,911 commission earned), runs monthly competitions, and recruits Reddit/TikTok creators by emailing affiliate@tymo-tech.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/tymo-beauty/', 'affiliate_network', 'compensation', 'An older LinkClicky directory entry lists TYMO on ShareASale at only 3% per sale, which conflicts with the brand''s own current partner page (15% base tier). The brand''s own published tiers govern, so 15% is recorded.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 18, 18, 12, 9, 4, '{"niche_fit": "Hair tools are a core beauty-UGC category \u2014 every product is demo-driven (straightening, curling, waving) and made for before/after video content.", "ugc_evidence": "The brand''s own partner page is built around creator reviews and demos, publishes affiliate earnings testimonials, runs monthly competitions and actively recruits TikTok and Reddit creators.", "compensation": "Published tiered cash commission on the brand''s own page \u2014 15% base, 20% growth, 25% ambassador \u2014 with an explicitly stated ''No earning cap''.", "contact_access": "A dedicated affiliate email (affiliate@tymo-tech.com) is published in the program terms, plus open registration on the partner page.", "opportunity_availability": "Registration is open on the brand''s own partner page with Level 1 commission active immediately upon registration.", "credibility": "Established DTC hair-tools brand with a large Amazon and TikTok Shop presence and published legal affiliate terms on its own store."}'::jsonb);
