  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 6, 6, 8, 4, '{"niche_fit": "Viral long-wear lip and brow products engineered for TikTok demonstration \u2014 peel-off reveals are natural UGC content.", "ugc_evidence": "TikTok''s own case study documents 20,000+ active affiliate partnerships, 300,000+ TikTok Shop units sold and structured creator programs (TTCX, TikTok One).", "compensation": "Affiliate routes exist on Impact and TikTok Shop, but published rates conflict (3% vs 5-10%) and no rate is published by the brand, so compensation scores low and the rate is null.", "contact_access": "Joining runs through Impact and TikTok Shop; no public creator contact was found on the pages checked.", "opportunity_availability": "The affiliate program operates at very large scale and is open to creators through TikTok Shop and Impact.", "credibility": "Established UK-founded brand with documented TikTok Shop sales volume and major retail momentum in the US."}'::jsonb);
