  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.tiktok.com/us/store/centellian24/7496101868706368413', 'listing', 'affiliate', 'Centellian24''s official TikTok Shop US store sells the full Madeca Derma range (Madeca Cream Time Reverse, Expert Madeca Cream Active Renew PDRN, Madeca Derma masks) with tens of thousands of units sold; product pages across the store carry ''Creator earns commission'' affiliate videos, confirming an active TikTok Shop affiliate route. TikTok Shop rates are set per product in-platform and are not published on the store pages, so the rate is null.', 'verified', now());
