  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://creator.fashionnova.com/ambassador-program-terms?anchor=policies', 'official_site', 'affiliate', 'Fashion Nova''s official Ambassador Program terms (fetched in full) state the program is open to influencers, content creators, athletes and artists, is free to join, pays commissions on qualifying purchases via unique tracking links, and requires a minimum of 250 followers on each channel used; the commission rate itself is shown inside the member dashboard rather than in the public terms.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://collabfeed.io/blog/how-fashion-nova-runs-their-creator-program', 'listing', 'compensation', 'CollabFeed''s program guide, quoting Fashion Nova''s own fashionnova.com FAQ verbatim (checked October 2026), records the FAQ answers: ''You earn 15% commission on every sale made through your link'' and ''At the moment, our Ambassador Program is affiliate-based only'', with no required deliverables; the application is at creator.fashionnova.com/become-ambassador.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.facebook.com/permalink.php?story_fbid=pfbid02k2zZD6q7KshEmf5Lpmj7S9Z1HYSWd5WBwpa4X6E9BAFFcmbSdz5QToW4PShwsQsfl&id=61595635406593', 'listing', 'ugc_collab', 'A screenshot of Fashion Nova''s own ambassador welcome email (November 2026) reads ''Welcome to one of the largest influencer networks in the world'' and ''Earn 15% commission on every sale you drive'' — the brand''s own description of a very large creator base, supporting a high saturation mark.', 'publicly_reported', now());
