  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 20, 16, 13, 9, 5, '{"niche_fit": "Pure fashion retailer with trend drops built for TikTok and Instagram try-on content \u2014 a core fashion-creator niche.", "ugc_evidence": "A dedicated creator portal and an affiliate-only ambassador program the brand itself calls one of the largest influencer networks in the world; creator content is the brand''s main marketing engine.", "compensation": "15% commission on every sale through the ambassador link, published in the brand''s own FAQ \u2014 a strong cash rate for apparel; no earnings cap is stated anywhere in the fetched terms, so the cap is honestly unknown.", "contact_access": "A public self-serve application on the brand''s own creator portal, linked from the fashionnova.com footer, with the full program terms published.", "opportunity_availability": "Open application today; the only stated bar is 250 followers on each channel used and not already being under a Fashion Nova influencer agreement.", "credibility": "One of the world''s best-known fast-fashion retailers with a long-running, publicly documented creator program."}'::jsonb);
