  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.crocs.com/affiliate-program/affiliate-program.html', 'official_site', 'affiliate', 'Crocs'' official affiliate program page (fetched in full) states the program runs via Impact, pays a standard commission rate of six percent (6%) per transaction, credits purchases for 30 days after the initial click, pays monthly, is free with no minimum sales requirement, and is open to any website; no earnings cap is mentioned, so the cap is recorded as unknown.', 'verified', now());
