  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 11, 10, 8, 5, '{"niche_fit": "Iconic footwear with constant collaboration drops and strong TikTok visibility \u2014 a proven fashion and lifestyle creator niche.", "ugc_evidence": "A formal affiliate program on Impact open to sites and creators, though run in a classic publisher style rather than a creator-first portal.", "compensation": "6% standard commission per transaction, stated on Crocs'' own program page, with a 30-day cookie and monthly payment; no cap statement appears, so the cap is unknown.", "contact_access": "The official program page walks applicants into the Impact application; no direct program email is published.", "opportunity_availability": "Open application to any launched website, free, with no minimum sales requirement; Crocs reviews and approves each site.", "credibility": "Global footwear brand with a long-established affiliate program and national retail presence."}'::jsonb);
