  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 10, 8, 7, 5, '{"niche_fit": "Premium trend fashion retailer whose whole brand is built on creator styling content \u2014 a top fashion-creator niche.", "ugc_evidence": "Two documented creator routes: the CJ publisher program and the REVOLVE + FWRD Ambassador program with an open application; influencer trips and capsule collections are core brand activity.", "compensation": "5% on all orders through the CJ affiliate program; ambassadors are reported at 15% cash. No earnings cap is published for either route, so the cap is unknown.", "contact_access": "No public program email found; joining runs through the CJ network application and the ambassador application on Revolve''s site.", "opportunity_availability": "Both routes take applications now; ambassador acceptance is vetted case by case with no stated follower floor.", "credibility": "Publicly traded, long-established premium fashion retailer with a documented decade of creator partnerships."}'::jsonb);
