  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 12, 13, 8, 3, '{"niche_fit": "Affordable fashion footwear is a staple TikTok Shop and try-on-haul category; the brand is a recognizable name in the niche.", "ugc_evidence": "A network affiliate program that explicitly negotiates higher rates and custom coupons with top-performing partners, plus an active TikTok Shop presence.", "compensation": "Tiered 4%-15% per sale on Awin \u2014 the 4% baseline floor is recorded, with the tier documented in evidence; no cap is published, so the cap is unknown.", "contact_access": "A published program email (affiliate@dreampairs.com) on the Awin profile plus the in-network application \u2014 strong direct access.", "opportunity_availability": "Open to Awin publishers now with a 30-day cookie; no follower minimum is published.", "credibility": "Established since 2009 with wide marketplace distribution, though a smaller public profile than the big footwear names."}'::jsonb);
