  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 10, 7, 9, 4, '{"niche_fit": "Viral comfort slip-ons are a proven TikTok fashion staple, and the brand sits on the owner''s TikTok Shop lead sheet.", "ugc_evidence": "Documented TikTok Shop free-sample creator collaborations with in-app commission offers, plus a network affiliate listing \u2014 creators are an active channel.", "compensation": "TikTok Shop rates are set per product (observed at 8-10% in live creator offers), so no single rate is recorded; a network listing quotes 8%. No cap is published, so the cap is unknown.", "contact_access": "Creator contact runs through the TikTok Shop seller chat inside the app; no public program email was found.", "opportunity_availability": "Open TikTok Shop affiliate enrollment for creators, with sample-based collaborations visible in current creator posts.", "credibility": "A Crocs, Inc. brand with mass retail distribution and sustained viral demand."}'::jsonb);
