  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 8, 8, 7, 5, '{"niche_fit": "Global sneaker and streetwear giant \u2014 a core fashion and sneaker-creator niche, though broader than pure fashion.", "ugc_evidence": "A long-running network affiliate program that PUMA''s own help pages route creators and publishers into; less creator-portal-driven than fashion-native brands.", "compensation": "Incentive-based tiers confirmed by PUMA''s own page, but no published flat rate and conflicting third-party figures (2-10%), so the rate is honestly null; no cap is published, so the cap is unknown.", "contact_access": "Applications run through CJ Affiliate from PUMA''s official affiliates help page; no direct program email is published.", "opportunity_availability": "Open CJ publisher application; PUMA approves partners selectively and requires a live content platform.", "credibility": "One of the world''s largest sportswear companies, publicly traded in Germany with a decades-long affiliate history."}'::jsonb);
