  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.buckedup.com/information/brand-ambassador-agreement', 'brand_site', 'affiliate', 'Bucked Up''s own Brand Ambassador Agreement (2025 Edition) sets the commission structure: 1 Star Ambassadors earn 10%, 2 Star 15%, 3-5 Star 20% on completed orders via promo codes/links (no commission on energy drinks, protein soda or the one-time 50% code). Earnings over $25/month are paid via PayPal; under $25 paid as store credit. No earnings cap is stated, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.buckedup.com/information/brand-ambassador-agreement', 'brand_site', 'ugc_collab', 'The agreement is a structured creator program: application reviewed in 3-5 business days, FTC disclosure rules, and a content-usage license for tagged ambassador content (UGC) across the brand''s platforms. Note: the agreement includes an exclusivity clause barring ambassadors from promoting competing supplement brands.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 15, 9, 7, 4, '{"niche_fit": "Pre-workout and sports nutrition are core fitness-creator territory and the brand is built around ambassador content.", "ugc_evidence": "A formal ambassador agreement with tracked codes/links and a UGC licensing clause for tagged content.", "compensation": "10% base (1 Star) rising to 20% at 3-5 Star, published in the brand''s own agreement; PayPal payment above $25/month.", "contact_access": "Full published agreement and application route on the brand''s own site; no public program email found.", "opportunity_availability": "Open application with 3-5 day review, but the exclusivity clause (no competing supplement promotion) limits creator flexibility.", "credibility": "Established national supplement brand (DAS Labs) with a formal, detailed legal agreement."}'::jsonb);
