  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.arzopa.com/pages/affiliate-program', 'official_site', 'affiliate_program', 'ARZOPA''s own Affiliate Program page (fetched) invites creators and publishers to apply through Impact or Awin under the headline ''Earn Up to 10% Commission'', with an FAQ explaining that commission rates vary by campaign, product, region and network. No earnings-cap statement appears on the page, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/72861', 'affiliate_network', 'compensation', 'ARZOPA''s Awin merchant profile (fetched in full) publishes a monthly tiered structure from October 1, 2026: Tier 1 (monthly sales below $3,000) pays 8%, Tier 2 ($3,000-$4,999) pays 10%, Tier 3 ($5,000+) pays 12%, with a 30-day cookie and the affiliate contact affiliatepartners@arzopa.com. The 8% base tier is recorded as the rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/72861', 'affiliate_network', 'general', 'The same Awin profile describes ARZOPA as a global smart display brand with roots in display technology dating back to 2008, selling portable monitors, digital photo frames and smart family calendars in more than 100 countries and regions.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 12, 13, 9, 4, '{"niche_fit": "Portable monitors and desk-setup displays are a core technology-creator niche on TikTok and YouTube.", "ugc_evidence": "The brand''s own program page and network profile explicitly recruit content creators, reviewers and publishers.", "compensation": "Published tiered rates: 8% base rising to 10% and 12% with monthly sales volume.", "contact_access": "Published affiliate contact email plus a public application page.", "opportunity_availability": "Open application through two major networks, Impact and Awin.", "credibility": "Display brand operating since 2008, sold in more than 100 countries through major marketplaces."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Newegg', 'https://www.newegg.com', 'Major US online retailer for PC components, consumer electronics and gaming gear, long popular with PC-build creators. Its affiliate program now runs on Rakuten Marketing, and a separate Newegg Creator Program pays video creators commission on tracked sales.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliatealerts@newegg.com', null, 'https://geniuslink.com/blog/newegg-affiliate-program-review/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten Advertising', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://geniuslink.com/blog/newegg-affiliate-program-review/.', null, 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://geniuslink.com/blog/newegg-affiliate-program-review/', 'listing', 'affiliate_program', 'Geniuslink''s fetched program review states the Newegg affiliate program was managed by CJ Affiliate from 2015 and has recently transferred to Rakuten Marketing, with a 7-day attribution window, category-based rates (around 1%, or 0.5% for returning customers, on components and hardware; better rates offered to editorial and content creators), no commission on TVs, mobile phones, game consoles or gift cards, and affiliate questions directed to affiliatealerts@newegg.com.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://reverbico.com/blog/newegg-affiliate-program/', 'listing', 'compensation', 'Reverbico''s fetched listing describes an active program across newegg.com and its sister sites (NeweggBusiness, Newegg Canada, ABS, Rosewill) with rates varying by product category (roughly 1-2% on many component categories) and a separate Newegg Creator Program for video creators offering sales commission, a 7-day cookie, custom links and access to its California studio. Published rates conflict between sources and vary by category, so commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 5, 8, 8, 5, '{"niche_fit": "One of the definitive retailers for PC-build, gaming and tech-review creator content.", "ugc_evidence": "A dedicated Newegg Creator Program for video creators exists alongside the classic affiliate program.", "compensation": "Rates are low (around 0.5-2% by category) and not published on an official program page, so scored low.", "contact_access": "Published affiliate contact email via a fetched program review; application runs through the network.", "opportunity_availability": "Open network application plus a creator-specific program.", "credibility": "One of the largest US technology retailers, operating for over two decades."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fanttik', 'https://fanttik.com', 'Consumer gadget and auto-accessory brand known for portable tire inflators, car vacuums, precision electric screwdrivers and jump starters, sold through its own store, Amazon and TikTok Shop and promoted heavily by gadget creators.', null, 'published') returning id into bid;
