  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopper.com', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.shopper.com/discount-codes/fanttik-com.', null, 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/discount-codes/fanttik-com', 'listing', 'affiliate_program', 'Shopper.com''s Fanttik page (fetched) carries a ''Fanttik Affiliate Program: Earn Up to 20% Commission'' listing, describing earnings of up to 20% commission with performance incentives and special promotion incentives. ''Up to 20%'' is a rate ceiling, not an earnings-cap statement, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wootfi.com/fanttik-affiliate-program/', 'listing', 'compensation', 'An older third-party listing reports the program tracked through GoAffPro and ShareASale at a 5% referral commission with a 45-day cookie, PayPal payouts and the contact publish@fanttik.com. This conflicts with Shopper.com''s up-to-20% headline, so commission_rate is null and the listing is flagged needs_review.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 8, 7, 7, 4, '{"niche_fit": "Tire inflators, car vacuums and mini tools are proven short-form gadget content.", "ugc_evidence": "The brand sells heavily through TikTok Shop and Amazon creator videos, and a formal affiliate program is listed by multiple sources.", "compensation": "A program with an up-to-20% headline exists, but the verified base rate is unclear (5% vs up to 20% conflict).", "contact_access": "Affiliate contact email available from a third-party listing only.", "opportunity_availability": "Joinable through listed affiliate platforms; no brand-hosted application page was found.", "credibility": "Established direct-to-consumer gadget brand with broad marketplace presence."}'::jsonb);
