  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/28831', 'affiliate_network', 'affiliate_program', 'VEVOR''s Awin merchant profile (fetched in full) states ''Baseline Commission: 2% - 10% per sale (tiered based on different traffic sources)'', a 30-day cookie, an average order value of $200, bonuses and custom coupons for top partners, and the contact collaboration@vevor.com. The 2% baseline floor is recorded as the rate. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/28831', 'affiliate_network', 'general', 'The same profile describes VEVOR as a cross-border export e-commerce brand of more than 10 years, selling across categories including Home & Garden, Kitchen & Dining, Tools and Pet Supplies.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/vevor/', 'listing', 'compensation', 'Third-party listings report different VEVOR rates on other networks (for example around 5% via ShareASale in LinkClicky data, 2% in Lasso''s listing), which is consistent with the Awin profile''s note that rates are tiered by traffic source; the Awin baseline is the recorded figure.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 8, 12, 8, 4, '{"niche_fit": "Huge catalog spanning home, garden, kitchen, tools and pet gives many creator angles.", "ugc_evidence": "Program markets to content publishers and DIY/review creators; product-review content is widespread.", "compensation": "Published range is 2-10%; the 2% floor is low, though the $200 average order value offsets it partly.", "contact_access": "Published collaboration email on the official network profile.", "opportunity_availability": "Open application through Awin.", "credibility": "Decade-old, very large cross-border seller with a US storefront."}'::jsonb);
