  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Costway Affiliate Program (Rakuten US / ShareASale CA)', 'https://www.costway.com/affiliate-program', 'https://www.costway.com/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.costway.com/affiliate-program', 'official_site', 'affiliate_program', 'Costway''s own Affiliate Program page (fetched, FAQ) states the program is free to join through its affiliate network, pays commissions monthly, provides banners and text links, and sets each affiliate''s commission rate based on the prior quarter''s sales. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.costway.com/m-affiliate-program', 'official_site', 'compensation', 'Costway''s official affiliate landing page states the US program runs through Rakuten with ''at least 4% commission of the order value'', benefits listed as ''Earn up to 6% commission per sale'', a 15-day cookie and monthly payment; the Canadian program runs through ShareASale at at least 6.5% and up to 10%. The US 4% floor is recorded as the rate.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 9, 9, 8, 4, '{"niche_fit": "Furniture and home goods are a core home-creator niche, with pet supplies as a secondary angle.", "ugc_evidence": "Program is aimed mainly at website publishers; video-creator recruitment is not emphasized.", "compensation": "Published 4% US floor, up to 6%, on a large furniture catalog with high order values.", "contact_access": "Public program pages and a clear network application route; no direct email found.", "opportunity_availability": "Open application for US-audience affiliates through Rakuten.", "credibility": "Large, established US online home retailer."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Scrub Daddy', 'https://scrubdaddy.com', 'Cleaning brand behind the smiley-faced FlexTexture sponge, made famous on Shark Tank and now one of TikTok Shop''s biggest affiliate-driven home brands, with an Awin programme whose stated objective is working with video content creators.', 'United States', 'published') returning id into bid;
