  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: high (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/31247.', null, 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/31247', 'affiliate_network', 'affiliate_program', 'Scrub Daddy''s Awin merchant profile (fetched) states the programme''s objective is to work with content creators across all social media platforms, with video content in demand and TikTok named as a market leader for the brand, which cites a creator list with a combined reach of over 20 million. The fetched profile publishes no commission rate, so commission_rate is null. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://influencers-time.com/advertiser/scrub-daddy-tiktok-shop-affiliate-program/', 'listing', 'ugc_collab', 'Influencers Time''s fetched advertiser profile documents that Scrub Daddy runs an OPEN TikTok Shop affiliate program that any creator can join to promote products and earn commission, with the brand''s low-friction approach generating a very high volume of affiliate videos. An open program at this documented scale is why creator_saturation is recorded as high.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/scrub-daddy/', 'listing', 'compensation', 'Lasso''s listing cites up to 5.25% for the Scrub Daddy program; that is a ceiling figure from a third-party listing with no published base rate, so it is not recorded as the rate.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 19, 7, 6, 9, 5, '{"niche_fit": "Cleaning and home-demo content is one of TikTok''s strongest niches, and this is its flagship product.", "ugc_evidence": "Creator-first brand: Awin programme built around video creators, plus a documented open TikTok Shop affiliate program.", "compensation": "Rate is not published on the network profile; only a third-party ceiling (up to 5.25%) exists.", "contact_access": "Network application only; no public partnerships email found.", "opportunity_availability": "Open TikTok Shop program any eligible creator can join, plus Awin.", "credibility": "Shark Tank brand in national retail; cited as the No. 3 sponge brand in the UK on its network profile."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Frost Buddy', 'https://www.frostbuddy.com', 'Insulated drinkware brand whose universal can coolers fit cans, bottles and cups, built almost entirely on TikTok Shop and Meta affiliate video, with a tiered FrostBuddy Affiliates creator program personally run by its founder.', 'United States', 'published') returning id into bid;
