  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FrostBuddy Affiliates Level 1 (TikTok Shop)', 'https://affiliates.frostbuddy.com/group', 'https://www.facebook.com/reel/2645704842592427/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.facebook.com/reel/2645704842592427/', 'listing', 'affiliate_program', 'In a fetched founder video post (August 2026), Frost Buddy founder Brock Mammoser announces the just-launched ''FrostBuddy Affiliates Level 1'' program for TikTok Shop affiliates, with sign-up at the brand''s affiliate site (affiliates.frostbuddy.com/group), weekly coaching calls, doubled commissions, and the option to submit videos for the brand to run as Meta ads. No fixed public commission percentage is published, so commission_rate is null and commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.instagram.com/reel/DcRIp7fgF8P/', 'listing', 'ugc_collab', 'A fetched founder Instagram post shows the brand''s creator page (''Get paid to post Frost Buddy videos'') with a ''Join the Creator Program'' form and VIP and Elite affiliate tiers, and states affiliates had generated over a million dollars in sales in a single month excluding TikTok Shop (founder-reported, unverified).', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.instagram.com/reel/DcL3ch4TXJ7/', 'listing', 'compensation', 'In another fetched founder post, the brand reports its top affiliate earned $43,000 in the prior two months, the #10 affiliate earned $13,000, and total affiliate-team GMV passed $231,000 (founder-reported figures, not independently verified).', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 18, 10, 8, 9, 3, '{"niche_fit": "Drinkware and gifting content fits home and lifestyle creators well.", "ugc_evidence": "The business is built on affiliate video: a structured, tiered creator program with weekly coaching calls.", "compensation": "No published rate, but founder-reported five-figure affiliate earnings and doubled-commission promotions.", "contact_access": "Public creator-program sign-up page; no email found.", "opportunity_availability": "Level 1 is open to any TikTok Shop affiliate, per the founder''s announcement.", "credibility": "Young direct-to-consumer brand; earnings figures are founder-reported and unverified."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Freezbone', 'https://www.freezbone.com', 'Dog enrichment brand selling fillable, freezable chew toys and natural treats, running a formal own-brand affiliate program with a published affiliate agreement, monthly payouts and content-licensing terms for pet creators.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.freezbone.com/pages/affiliate-agreement.', 'https://www.freezbone.com/pages/affiliate-agreement', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Freezbone Affiliate Program', 'https://www.freezbone.com/pages/affiliate-agreement', 'https://www.freezbone.com/pages/affiliate-agreement', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.freezbone.com/pages/affiliate-agreement', 'official_site', 'affiliate_program', 'Freezbone''s own Affiliate Agreement (fetched in full) establishes a real own-brand program: affiliates earn commissions through affiliate links, coupon codes and dedicated landing pages, grant the brand a license to reuse their content (including whitelisting), and are paid between the 1st and 10th of each month. The agreement publishes no commission rate (rates are set and may be modified at the company''s discretion), so commission_rate is null. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.freezbone.com/pages/affiliate-agreement', 'official_site', 'compensation', 'The same agreement (Freezbone Inc., governed by Florida law) details commission clawbacks for returns and chargebacks and a minimum-payout mechanism, confirming an operating, terms-backed program rather than a gifting scheme.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 6, 6, 7, 3, '{"niche_fit": "Dog enrichment toys and treats are a strong, demonstrable pet-content niche.", "ugc_evidence": "The program is built around creator content, with licensing and whitelisting terms written for UGC.", "compensation": "No rate is published anywhere in the agreement, so compensation cannot be scored higher.", "contact_access": "Program terms live on the brand''s own site; no public contact email found.", "opportunity_availability": "Participation begins with an affiliate account under the published agreement.", "credibility": "Small, young brand, but it publishes a formal legal affiliate agreement."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Potaroma', 'https://potaroma.com', 'Cat-toy brand behind the viral flopping fish and a wide range of interactive, catnip and motion-activated toys, sold through its own store, Amazon, Chewy and a high-volume TikTok Shop storefront (POTAROMA LLC, Aurora, Colorado) with creator commission selling.', 'United States', 'published') returning id into bid;
