  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'TikTok Shop', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://shop.tiktok.com/us/pdp/interactive-cat-kicker-toy-with-motion-sensor-usb-chargeable/1731978601542357035?source=product_detail&enter_method=url_semantic_301.', null, 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://potaroma.com/', 'official_site', 'general', 'Potaroma''s own site (fetched) presents the brand as a specialist in cat toys integrating research, design and production, holding a leading position in the US online cat toy market, with interactive electric toys, catnip pillow toys and dog toys.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.tiktok.com/us/pdp/interactive-cat-kicker-toy-with-motion-sensor-usb-chargeable/1731978601542357035?source=product_detail&enter_method=url_semantic_301', 'listing', 'affiliate_program', 'Potaroma sells on TikTok Shop through its own storefront (seller POTAROMA LLC, Aurora, Colorado; the shop shows roughly 225.7K items sold and a 4.4 rating), and its product pages carry TikTok Shop''s creator-commission selling (''Creator earns commission''). TikTok Shop rates are set per product and are not published as a single program rate, so commission_rate is null and commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.tiktok.com/us/pdp/interactive-cat-kicker-toy-with-motion-sensor-usb-chargeable/1731978601542357035?source=product_detail&enter_method=url_semantic_301', 'listing', 'compensation', 'A Potaroma Pets TikTok Shop collaboration invitation seen in creator outreach offered 15% commission plus a free sample on one product, confirming active target collaborations; because TikTok Shop rates are set per product and per collaboration, no single rate is recorded.', 'publicly_reported', now());
