  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PetPivot Affiliate Program (Impact / Awin / UpPromote)', 'https://petpivot.com/pages/affiliate-program', 'https://petpivot.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://petpivot.com/pages/affiliate-program', 'official_site', 'affiliate_program', 'PetPivot''s own Affiliate Program page (fetched in full) invites creators, bloggers, reviewers, publishers and pet communities to apply through Impact, Awin or its UpPromote portal (aff.petpivot.com), and states that commission rates, attribution windows and payment terms are listed in each platform''s program agreement - they are not published on the page, so commission_rate is null. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
