  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 8, 9, 8, 3, '{"niche_fit": "Self-cleaning litter boxes are highly demonstrable pet-tech with strong review content demand.", "ugc_evidence": "Program is aimed squarely at cat creators and backed by structured bonus campaigns.", "compensation": "Rates live inside network agreements and are not public; campaign boosts are documented.", "contact_access": "Own affiliate page with three clear join routes.", "opportunity_availability": "Open application (subject to review) on three platforms.", "credibility": "Young, focused cat-tech brand; limited track record so far."}'::jsonb);
